import styles from "@/app/home.module.css";

/** Projected, occluded terrain generated by scripts/generate-terrain.mjs. */
export function Landscape({ id, quiet = false, reverse = false }: { id: string; quiet?: boolean; reverse?: boolean }) {
  return <div data-terrain={id} className={`${styles.terrain} ${quiet ? styles.quiet : ""} ${reverse ? styles.reverse : ""}`} aria-hidden="true">
    {/* Native SVG image keeps the dense decorative mesh out of the React/HTML tree. */}
    {/* eslint-disable-next-line @next/next/no-img-element */}
    <img src="/terrain-surface.svg" alt="" width="1600" height="440" draggable={false}/>
  </div>;
}
